// Persistent display snapshots. Never use these as transaction authorization.
import { CHAIN, CONTRACTS } from './chain-config.js';
import { registerReadCacheInvalidator } from './read-provider.js';
import { subscribe } from './store.js';
import { displaySnapshotDomains, transactionAffects } from './transaction-effects.js';

export const DISPLAY_REFRESH_MS = 6 * 60 * 60_000;
const RETRY_MS = 60_000;
const memory = new Map(), flights = new Map(), retries = new Map(), listeners = new Set();
let generation = 0;
let finishedTicketFloor = null;
const revisions = new Map();
const prefix = () => `degenerus:display:v1:${CHAIN.id}:${CONTRACTS.GAME}:${CONTRACTS.DEITY_PASS}:${CONTRACTS.AFKING_SUB_TOKEN}:`.toLowerCase();
const keyFor = key => prefix() + String(key).toLowerCase();
function finishedTicketKey(key) {
  if (finishedTicketFloor == null) return false;
  const text = String(key).toLowerCase();
  const match = /^ticket:\/player\/0x[0-9a-f]{40}\/(?:tickets\/by-trait|foil)\?/.test(text)
    ? /[?&]level=(\d+)(?:&|$)/.exec(text)
    : /^ticket:deity:0x[0-9a-f]{40}:(\d+):/.exec(text);
  return Boolean(match && Number(match[1]) < finishedTicketFloor);
}

/** Delete bulky ticket/foil/trait snapshots only after their draw is finished. */
export function pruneFinishedTicketSnapshots(state) {
  if (state?.level == null || state.gameOver === true) return 0;
  const level = Number(state.level);
  if (!Number.isSafeInteger(level) || level < 0) return 0;
  if (!['PURCHASE', 'JACKPOT'].includes(state.phase)
    && typeof state.jackpotPhaseFlag !== 'boolean') return 0;
  const drawing = state.phase === 'JACKPOT' || state.jackpotPhaseFlag === true
    || state.rngLockedFlag === true || state.rngLocked === true;
  const floor = state.phaseTransitionActive === true ? level + 1 : drawing ? level : level + 1;
  if (finishedTicketFloor === floor) return 0;
  finishedTicketFloor = floor;
  const scope = prefix();
  const keys = new Set([...memory.keys(), ...flights.keys(), ...retries.keys()]);
  try {
    for (let i = 0; i < localStorage.length; i++) keys.add(localStorage.key(i));
  } catch (_) { /* memory cleanup still works */ }
  let removed = 0;
  for (const id of keys) {
    if (!id?.startsWith(scope) || !finishedTicketKey(id.slice(scope.length))) continue;
    // An in-flight historical read must not put the deleted payload back.
    revisions.set(id, (revisions.get(id) ?? 0) + 1);
    memory.delete(id); flights.delete(id); retries.delete(id);
    try { localStorage.removeItem(id); } catch (_) { /* optional storage */ }
    removed++;
  }
  return removed;
}
function encode(_key, value) {
  if (typeof value === 'bigint') return { $display: 'bigint', value: String(value) };
  if (value instanceof Map) return { $display: 'map', value: [...value] };
  if (value instanceof Set) return { $display: 'set', value: [...value] };
  return value;
}
function decode(_key, value) {
  if (value?.$display === 'bigint') return BigInt(value.value);
  if (value?.$display === 'map') return new Map(value.value);
  if (value?.$display === 'set') return new Set(value.value);
  return value;
}
function emit(key) { for (const listener of listeners) { try { listener(key); } catch (_) {} } }
export function subscribeDisplayCache(listener) { listeners.add(listener); return () => listeners.delete(listener); }

export function readDisplaySnapshot(key) {
  if (finishedTicketKey(key)) return null;
  const id = keyFor(key);
  if (memory.has(id)) return memory.get(id);
  try {
    const entry = JSON.parse(localStorage.getItem(id), decode);
    if (!entry || entry.value == null || !Number.isSafeInteger(entry.savedAt)
      || entry.savedAt < 0 || entry.savedAt > Date.now()) return null;
    memory.set(id, entry);
    return entry;
  } catch (_) { return null; }
}

export function writeDisplaySnapshot(key, value, savedAt = Date.now()) {
  if (value == null || finishedTicketKey(key)) return;
  const id = keyFor(key), entry = { value, savedAt };
  memory.set(id, entry);
  while (memory.size > 128) memory.delete(memory.keys().next().value);
  try { localStorage.setItem(id, JSON.stringify(entry, encode)); } catch (_) { /* Memory still works. */ }
}

/** Expire saved data without blanking it, and reject pre-transaction writes. */
export function invalidateDisplaySnapshots(matches = null) {
  const scope = prefix();
  const keys = new Set([...memory.keys(), ...flights.keys(), ...retries.keys()].filter(key => key.startsWith(scope)));
  try { for (let i = 0; i < localStorage.length; i++) {
    const key = localStorage.key(i); if (key?.startsWith(scope)) keys.add(key);
  } } catch (_) {}
  const changed = [];
  for (const id of keys) {
    const key = id.slice(scope.length);
    if (matches && !matches(key)) continue;
    revisions.set(id, (revisions.get(id) ?? 0) + 1);
    flights.delete(id); retries.delete(id);
    const entry = readDisplaySnapshot(key);
    if (entry) writeDisplaySnapshot(key, entry.value, 0);
    changed.push(key);
  }
  // A filtered invalidation must not wake every inventory/catalog listener.
  if (!matches) emit(null);
  else changed.forEach(emit);
}
registerReadCacheInvalidator(context => {
  const logs = context?.receipt?.logs;
  // New deity purchases emit from the NFT contract.
  // An unrelated flip/claim must not throw away the whole ownership catalog.
  const deityChanged = !Array.isArray(logs) || logs.some(log =>
    String(log?.address || '').toLowerCase() === String(CONTRACTS.DEITY_PASS).toLowerCase());
  invalidateDisplaySnapshots(key => (key !== 'deity-catalog' || deityChanged)
    && transactionAffects(context?.effects, displaySnapshotDomains(key)));
});

// Draws can award tickets and debit subscriptions without this wallet sending
// a transaction. Refresh once on a new game day, not on each UI poll.
subscribe('app.daySync', state => {
  const day = Number(state?.day);
  if (!Number.isInteger(day) || day <= 0) return;
  const previous = readDisplaySnapshot('game-day')?.value;
  if (previous === day) return;
  writeDisplaySnapshot('game-day', day);
  if (previous != null) invalidateDisplaySnapshots(key => key.startsWith('ticket:') || key.startsWith('afking:'));
});

// Ticket minting/settlement and AFKing delivery can happen without a wallet
// transaction. Changes in pools or block headers alone do not expire holdings.
subscribe('app.gameState', state => {
  if (!state || state.level == null) return;
  pruneFinishedTicketSnapshots(state);
  const context = JSON.stringify([state.phaseCurrentDay ?? state.dailyIdx, state.level,
    state.phase, state.rngLocked, state.phaseTransitionActive, state.ticketsFullyProcessed,
    state.lastDailyCompletedAt]);
  const previous = readDisplaySnapshot('game-context')?.value;
  if (previous === context) return;
  writeDisplaySnapshot('game-context', context);
  if (previous != null) invalidateDisplaySnapshots(key => key.startsWith('ticket:') || key.startsWith('afking:'));
});

/** Saved values resolve immediately; one background refresh repairs stale data. */
export async function loadDisplaySnapshot(key, read, { fresh = false, maxAge = DISPLAY_REFRESH_MS } = {}) {
  const id = keyFor(key), saved = readDisplaySnapshot(key);
  const age = saved ? Date.now() - saved.savedAt : Infinity;
  if (!fresh && saved && saved.savedAt > 0 && age < maxAge) return saved.value;
  if (!fresh && (retries.get(id) ?? 0) > Date.now()) return saved?.value ?? null;
  if (!flights.has(id)) {
    const revision = generation;
    const keyRevision = revisions.get(id) ?? 0;
    const current = () => revision === generation && keyRevision === (revisions.get(id) ?? 0);
    const flight = Promise.resolve().then(read).then(value => {
      if (value == null) throw new Error('Display snapshot unavailable');
      if (current()) {
        const changed = JSON.stringify(saved?.value, encode) !== JSON.stringify(value, encode);
        writeDisplaySnapshot(key, value);
        retries.delete(id);
        if (changed) emit(key);
      }
      return value;
    }).catch(error => {
      if (current() && error?.name !== 'AbortError') retries.set(id, Date.now() + RETRY_MS);
      throw error;
    }).finally(() => { if (flights.get(id) === flight) flights.delete(id); });
    flights.set(id, flight);
  }
  const flight = flights.get(id);
  if (saved && !fresh) { void flight.catch(() => {}); return saved.value; }
  return flight;
}

/** Test seam: emulate a new page without clearing persistent storage. */
export function resetDisplayCacheMemoryForTest() {
  generation++; finishedTicketFloor = null; memory.clear(); flights.clear(); retries.clear(); revisions.clear();
}
